// @ts-check
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import remarkBaseLinks from './src/plugins/remark-base-links.mjs';
import rehypeTableCorner from './src/plugins/rehype-table-corner.mjs';

const site = 'https://butyavk.github.io';
const base = '/live-coding';

/** Sidebar group helper: one autogenerated group per content directory. */
const group = (label, ru, directory, collapsed = false) => ({
  label,
  translations: { ru },
  collapsed,
  items: [{ autogenerate: { directory } }],
});

/**
 * The mock interview pages (src/pages/mock/, one per task) are not for search engines: they carry
 * noindex and stay out of the site search, and this drops them from the sitemap that Starlight
 * writes. It runs after the sitemap, as it comes after Starlight in `integrations`.
 */
const sitemapWithoutMocks = {
  name: 'live-coding:sitemap-without-mocks',
  hooks: {
    'astro:build:done': async ({ dir }) => {
      for (const f of await readdir(dir)) {
        if (!/^sitemap-\d+\.xml$/.test(f)) continue;
        const file = new URL(f, dir);
        const xml = await readFile(file, 'utf8');
        await writeFile(file, xml.replace(/<url>.*?<\/url>/gs, (u) => (/<loc>[^<]*\/mock\/[^<]*<\/loc>/.test(u) ? '' : u)));
      }
    },
  },
};

export default defineConfig({
  site,
  base,
  trailingSlash: 'always',
  markdown: {
    remarkPlugins: [[remarkBaseLinks, { base }]],
    rehypePlugins: [rehypeTableCorner],
  },
  vite: {
    // PGlite and Pyodide run in workers from public/runtime/ (see scripts/copy-runtimes.mjs);
    // the build-time script imports PGlite directly, the pages never do.
    optimizeDeps: { exclude: ['@electric-sql/pglite', 'pyodide'] },
  },
  integrations: [
    starlight({
      title: {
        en: 'Live Coding Map',
        ru: 'Карта лайвкодинга',
      },
      description:
        'Prepare for SQL and Python live-coding interviews: a skill map, study plans, an interview protocol and hands-on practice with PostgreSQL and Python running in your browser.',
      logo: { src: './src/assets/logo.svg', replacesTitle: false },
      favicon: '/favicon.svg',
      routeMiddleware: './src/route-data.ts',
      defaultLocale: 'root',
      locales: {
        root: { label: 'English', lang: 'en' },
        ru: { label: 'Русский', lang: 'ru' },
      },
      social: [
        { icon: 'github', label: 'GitHub', href: 'https://github.com/butyavk/live-coding' },
      ],
      editLink: {
        baseUrl: 'https://github.com/butyavk/live-coding/edit/main/',
      },
      lastUpdated: true,
      customCss: [
        '@fontsource-variable/onest',
        '@fontsource-variable/jetbrains-mono',
        './src/styles/theme.css',
      ],
      components: {
        Footer: './src/components/overrides/Footer.astro',
      },
      sidebar: [
        group('Start here', 'С чего начать', 'start'),
        group('SQL foundations', 'Основа SQL', 'sql'),
        group('SQL patterns', 'Приёмы SQL', 'sql-patterns'),
        group('Python for live coding', 'Python для лайвкодинга', 'python'),
        group('Practice: SQL tasks', 'Практика: задачи SQL', 'sql-tasks'),
        group('Practice: Python tasks', 'Практика: задачи Python', 'python-tasks'),
        group('Reference', 'Справочник', 'reference'),
        group('About', 'О проекте', 'about', true),
      ],
    }),
    sitemapWithoutMocks,
  ],
});
